%[text] ## Demo2: Feedback Control Experiment
%[text] use PI/PD/PID Controller and compare the performance.
%[text] modify the P, I, D gain and (if you have time) add other filters for further analysis and performance enhancement.
%%
%[text] ### STEP 1: DESIGN FEEDBACK CONTROLLER
%[text] load settings for the experiment
clear; close all;

omega = 15; % set by yourself [rad/s] (not [Hz])
Smax = 2; % Maximum gain of sensitivity function (= 6 dB)

save_results = true;
repeat_count = 1;
hold_margin_s = 1.0;

cfg = experiment.ExperimentConfig.defaults();
expected_Ts = 1 / cfg.env.task_rate_hz;
plant_mat_path = fullfile(experiment.scenario.default_result_dir(), "plant.mat");
plant_data = experiment.exp0n.load_plant_data( ...
  plant_mat_path, "expected_sample_time_s", expected_Ts);

Pd = plant_data.Pd;
Pdn = plant_data.Pdn;
Jn = double(plant_data.Jn);
Dn = double(plant_data.Dn);
Ts = double(plant_data.Ts);

%[text] $K\\;\\textrm{＝}\\;k\_p +\\frac{k\_i }{s}+k\_d \\frac{s}{1+T\_f s}${"editStyle":"visual"}
%[text] see what happens when $k\_p${"editStyle":"visual"}, $k\_i${"editStyle":"visual"}, $k\_d${"editStyle":"visual"} is changed.
% Kpi = experiment.exp02.designpi(Dn/Jn, 0, 1/Jn, omega); % uncomment to use PI controller
% Kpd = experiment.exp02.designpd(Dn/Jn, 0, 1/Jn, omega); % uncomment to use PD controller
Kpid = experiment.exp02.designpid(Dn/Jn, 0, 1/Jn, omega); % uncomment to use PID controller
% Kpid.Kp = 0; % set Kp to 0
% Kpid.Ki = 0; % set Ki to 0
% Kpid.Kd = 0; % set Kd to 0
%[text] ### (optional: Design other controllers)
%[text] (hint: change to I-PD, add leadlag filter, add notch filter)
%%
%[text] ### Check the stability and performance of FB Controller (Always check before experiment!!!)
%[text] use nyquist and sensitivity plot
%[text] (note: Pd is actual system, Pdn is modelled system)
Kd = c2d(Kpid, Ts, "tustin"); % digital feedback controller

trajectory = experiment.exp0n.load_trajectory( ...
  "expected_sample_time_s", Ts, "table_max_n", cfg.env.table_max_n);
scenario = experiment.scenario.exp02( ...
  plant_data, trajectory, "cfg", cfg, "omega", omega, "Smax", Smax, ...
  "Kd", Kd, "repeat_count", repeat_count, ...
  "hold_margin_s", hold_margin_s, "save_results", save_results);
stability = experiment.exp02.stability_check( ... %[output:group:44547ab9] %[output:585aad10] %[output:03491ef7]
  Pd, Pdn, Kd, Smax, ... %[output:585aad10] %[output:03491ef7]
  "error_id", "experiment:exp02_feedback:sensitivityLimitExceeded"); %[output:group:44547ab9] %[output:585aad10] %[output:03491ef7]
stability_summary = table( ...
  stability.max_sensitivity, Smax, stability.limit_exceeded, ...
  VariableNames=["measuredSensitivityPeak", "limit", "limitExceeded"]);
display(stability_summary); %[output:5e9a8503]
%%
%[text] ### STEP 2: FEEDBACK EXPERIMENT
%[text] set reference trajectory
r = trajectory.p;
t = trajectory.t;

figure; %[output:71d6e4e6]
plot(t, r); %[output:71d6e4e6]
grid off; %[output:71d6e4e6]
xlabel("Time [s]"); ylabel("Position [rad]"); %[output:71d6e4e6]

%%
%[text] execute the VirtualMotor experiment through the shared workflow
workflow = experiment.workflow.run_exp02(scenario);
signals = workflow.signals;
feedback_metrics = workflow.metrics;
t = signals.time_s;
r = repmat(r, repeat_count, 1);
y = signals.position_act; % output load position [rad]
e = signals.error; % tracking error [rad]
u = signals.control_input; % control input [A]

%%
%[text] save experiment data
completed_at_utc = string(datetime("now", "TimeZone", "UTC", ...
  "Format", "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"));
artifact_summary = table( ...
  workflow.artifacts.saved, string(workflow.artifacts.result), ...
  completed_at_utc, ...
  VariableNames=["saved", "feedbackResult", "completedAtUtc"]);
display(artifact_summary); %[output:1d4ebfb5]
%%
%[text] ### STEP 3: Analyze the results of the experiment
%[text] download data
%%
%[text] plot tracking result of feedback control
experiment.plot.feedback_result(signals, feedback_metrics); %[output:54e31c3c]

%[text] display tracking metrics
tracking_summary = table( ...
  feedback_metrics.tracking_error_l2, ...
  feedback_metrics.tracking_error_rms, ...
  feedback_metrics.tracking_error_peak, ...
  feedback_metrics.final_error, ...
  feedback_metrics.max_abs_control_input, ...
  VariableNames=["errorL2", "errorRMS", "errorPeak", ...
    "finalError", "maxInput_A"]);
display(tracking_summary); %[output:16c3cead]


